// Generates src/lib/countries.ts from the `world-countries` dataset (a
// devDependency). Run with `node scripts/gen-countries.mjs` after bumping the
// dataset. The generated file is committed so the app has no runtime dependency
// on world-countries — just a small, static, offline ISO 3166-1 list.
import countries from "world-countries";
import { writeFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { dirname, join } from "node:path";

const here = dirname(fileURLToPath(import.meta.url));
const out = join(here, "..", "src", "lib", "countries.ts");

const rows = countries
  .map((c) => ({ code: c.cca2, name: c.name.common, flag: c.flag }))
  .filter((c) => /^[A-Z]{2}$/.test(c.code))
  .sort((a, b) => a.name.localeCompare(b.name));

const body = rows
  .map((c) => `  { code: ${JSON.stringify(c.code)}, name: ${JSON.stringify(c.name)}, flag: ${JSON.stringify(c.flag)} },`)
  .join("\n");

const file = `// AUTO-GENERATED by scripts/gen-countries.mjs — do not edit by hand.
// Static ISO 3166-1 country list (${rows.length} entries) for the submit form's
// country picker. Bundled offline: no API call, no rate limit, instant search.

export interface Country {
  /** ISO 3166-1 alpha-2 code, e.g. "BG". */
  code: string;
  /** Common English name, e.g. "Bulgaria". */
  name: string;
  /** Flag emoji, e.g. "🇧🇬". */
  flag: string;
}

export const COUNTRIES: Country[] = [
${body}
];

const BY_CODE = new Map(COUNTRIES.map((c) => [c.code, c]));

/** Look up a country by ISO alpha-2 code (case-insensitive). */
export function countryByCode(code: string | null | undefined): Country | undefined {
  return code ? BY_CODE.get(code.toUpperCase()) : undefined;
}
`;

writeFileSync(out, file);
console.log(`Wrote ${rows.length} countries to ${out}`);
